def handler(event):
    text = event.get("text") if isinstance(event, dict) else None
    if not text or not isinstance(text, str):
        return {"ok": False, "error": "text (string) is required"}
    try:
        custom_categories = event.get("categories")
        if custom_categories and isinstance(custom_categories, list):
            # Use custom categories with keyword matching
            t_lower = text.lower()
            words = set(re.findall(r'\b\w+\b', t_lower))
            scores = {}
            for cat in custom_categories:
                cat_words = set(re.findall(r'\b\w+\b', cat.lower()))
                overlap = len(words & cat_words)
                scores[str(cat)] = overlap
        else:
            t_lower = text.lower()
            words = set(re.findall(r'\b\w+\b', t_lower))
            scores = {}
            for cat, keywords in DEFAULT_CATEGORIES.items():
                scores[cat] = len(words & keywords)

        best = max(scores, key=scores.get)
        best_score = scores[best]
        total = sum(scores.values()) or 1
        confidence = round(best_score / total, 4) if best_score > 0 else 0.0
        if best_score == 0:
            best = "general"
            confidence = 0.0

        return {
            "ok": True,
            "result": {"category": best, "confidence": confidence},
            "category": best,
            "confidence": confidence,
            "scores": {k: v for k, v in sorted(scores.items(), key=lambda x: x[1], reverse=True)}
        }
    except Exception as e:
        return {"ok": False, "error": str(e)}
